'''Read-only summaries of workflow tables in a node.'''
import argparse
from datetime import datetime, timedelta, timezone
import json
import os
from pathlib import Path
import re

EVERY = re.compile(r'[1-9][0-9]*[rsmhd]')
SIGNED_INT = re.compile(r'[+-]?[0-9]+')
SECONDS = {'s': 1, 'm': 60, 'h': 3600, 'd': 86400}
REQUIRED = {
    'routines': ('name', 'every', 'last_time', 'last_code'),
    'schedule': ('name', 'at', 'claimed'),
}


def reject_constant(value):
    raise ValueError('non-finite JSON number: ' + value)


def load_json(path):
    # Avoid changing access times where the filesystem permits O_NOATIME.
    try:
        fd = os.open(path, os.O_RDONLY | getattr(os, 'O_NOATIME', 0))
    except PermissionError:
        fd = os.open(path, os.O_RDONLY)
    with os.fdopen(fd, encoding='utf-8') as stream:
        return json.load(stream, parse_constant=reject_constant)


def issue(table, row, why):
    return {'table': table, 'row': row, 'why': why}


def read_table(node, table):
    try:
        value = load_json(node / 'wf' / (table + '.json'))
    except FileNotFoundError:
        return [], []
    except (OSError, UnicodeError, ValueError):
        return [], [issue(table, None, 'bad_table')]
    if (not isinstance(value, dict) or value.get('contract') != 'wf-table/1'
            or not isinstance(value.get('columns'), list)
            or not all(isinstance(item, str) for item in value['columns'])
            or not isinstance(value.get('rows'), list)):
        return [], [issue(table, None, 'bad_table')]
    return value['rows'], []


def timestamp(text, tz):
    value = datetime.fromisoformat(text)
    return value.replace(tzinfo=tz) if value.tzinfo is None else value


def routine(row, now):
    every = row['every']
    if EVERY.fullmatch(every) is None:
        raise ValueError('invalid every')
    text = row['last_time']
    last = timestamp(text, now.tzinfo) if text else None
    raw_code = row['last_code']
    if raw_code == '':
        code = None
    elif raw_code == 'running':
        code = 'running'
    elif SIGNED_INT.fullmatch(raw_code):
        code = int(raw_code)
    else:
        raise ValueError('invalid last_code')

    next_time = None
    next_text = None
    if last is not None and every[-1] != 'r':
        next_time = last + timedelta(seconds=int(every[:-1]) * SECONDS[every[-1]])
        next_text = next_time.astimezone(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    if code == 'running':
        state = 'running'
    elif last is None:
        state = 'never'
    elif isinstance(code, int) and code != 0:
        state = 'failed'
    elif next_time is not None and now >= next_time:
        state = 'overdue'
    else:
        state = 'ok'
    return {'name': row['name'], 'every': every, 'last_time': text or None,
            'last_code': code, 'state': state, 'next': next_text}


def scheduled(row, now):
    at = timestamp(row['at'], now.tzinfo)
    state = 'interrupted' if row['claimed'] else 'due' if at <= now else 'pending'
    return {'name': row['name'], 'at': row['at'], 'state': state}


def summarize(node, now):
    result = {'v': 1, 'routines': [], 'schedule': [],
              'counts': {'routines': dict.fromkeys(('running', 'never', 'failed', 'overdue', 'ok'), 0),
                         'schedule': dict.fromkeys(('interrupted', 'due', 'pending'), 0)},
              'bad': []}
    for table in ('routines', 'schedule'):
        rows, problems = read_table(node, table)
        result['bad'].extend(problems)
        seen = set()
        for index, row in enumerate(rows):
            name = row.get('name') if isinstance(row, dict) else None
            if isinstance(name, str) and name:
                if name in seen:
                    result['bad'].append(issue(table, index, 'dup_name'))
                    continue
                seen.add(name)
            if (not isinstance(row, dict) or not all(isinstance(v, str) for v in row.values())
                    or any(key not in row for key in REQUIRED[table])
                    or not isinstance(name, str) or not name):
                result['bad'].append(issue(table, index, 'bad_row'))
                continue
            try:
                item = routine(row, now) if table == 'routines' else scheduled(row, now)
            except (ValueError, OverflowError):
                result['bad'].append(issue(table, index, 'bad_row'))
                continue
            result[table].append(item)
            result['counts'][table][item['state']] += 1
        result[table].sort(key=lambda item: item['name'])
    result['bad'].sort(key=lambda item: (item['table'], -1 if item['row'] is None else item['row'], item['why']))
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description='Summarize node workflow tables without writing')
    parser.add_argument('folder', type=Path)
    parser.add_argument('--now', required=True)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error('folder must be a directory')
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error('--now must be an ISO datetime with a timezone')
    if now.tzinfo is None or now.utcoffset() is None:
        parser.error('--now must have a timezone')
    print(json.dumps(summarize(args.folder, now), separators=(',', ':'), allow_nan=False))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
